// Auxiliary rules-only diagnostic. Generated by exact extraction, never used
// as the default product benchmark or as full-suite acceptance evidence.
import fs from 'node:fs';
import path from 'node:path';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {performance} from 'node:perf_hooks';
import {Measurements} from './inputs/baseline/tool/perf/metrics.mjs';
import {DiagnosticProbe} from './diagnostic_probe.mjs';
const require = createRequire(import.meta.url);
const root = path.dirname(fileURLToPath(import.meta.url));
const [role, output, observationMode] = process.argv.slice(2);
assert.ok(['baseline', 'candidate'].includes(role));
assert.ok(output && path.isAbsolute(output));
assert.ok(['off', 'auxiliary'].includes(observationMode));
assert.equal(process.env.ABC_PERF_TIER, 'ci');
assert.equal(process.env.ABC_PERF_WARMUP, '5');
assert.equal(process.env.ABC_PERF_CYCLES, '25');
assert.equal(typeof global.gc, 'function');
const manifest = JSON.parse(fs.readFileSync(path.join(root, 'input-manifest.json')));
const inputRoot = path.join(root, 'inputs', role);
assert.equal(process.cwd(), inputRoot);
for (const [relative, expected] of Object.entries(manifest.roles[role].files)) {
  const data = fs.readFileSync(path.join(inputRoot, relative));
  assert.equal(data.length, expected.bytes);
  assert.equal(createHash('sha256').update(data).digest('hex'), expected.sha256);
}
const bench = new Measurements('wasm-rules-only-diagnostic');
// A file snapshot is not a Git checkout. Do not fabricate clean-worktree proof.
bench.report.source = {commit: manifest.roles[role].sourceCommit, worktreeCommit: null,
  dirty: null, commitSource: 'fixed-input-sha256-manifest', sourceProof: manifest.roles[role]};
bench.report.toolchain.emscripten = '5.0.7';
bench.report.methodology.rulesOnlyDiagnostic = true;
bench.report.methodology.gcDiagnosticEnabled = observationMode === 'auxiliary';
bench.report.methodology.diagnosticObservation = observationMode;
bench.report.methodology.observationLimit = 'Memory sampling and synchronous writes occur outside original operation timers; observer callbacks can overlap awaited operations. Instrumentation changes allocation/GC scheduling; compare only like observation modes.';
bench.report.diagnostic = {scope: manifest.scope, originalFailure: manifest.originalFailure,
  pairedEvidence: manifest.pairedEvidence, overallAcceptance: 'unestablished',
  inputManifestSha256: createHash('sha256').update(fs.readFileSync(path.join(root, 'input-manifest.json'))).digest('hex'),
  rulesCycleSha256: manifest.rulesCycleSha256};
bench.journal(output);
const modules = new Map();
async function load(key) {
  if (!modules.has(key)) {
    const file = path.join(inputRoot, 'web/engine/world.js');
    const binary = fs.readFileSync(file.replace(/\.js$/, '.wasm'));
    const module = await require(file)({wasmBinary: binary});
    bench.report.toolchain.artifacts.push({id: 'wld-wasm', bytes: binary.length,
      sha256: createHash('sha256').update(binary).digest('hex'),
      loaderSha256: createHash('sha256').update(fs.readFileSync(file)).digest('hex')});
    modules.set(key, module); bench.modules.push(module);
  }
  return modules.get(key);
}
const measure = (id, f, fn) => bench.measure(id, f.id, f.bytes.length, fn);
const own = (prefix, id) => bench.owners.add(`${prefix}:${id}`);
const release = (prefix, id) => bench.owners.delete(`${prefix}:${id}`);
const probe = observationMode === 'auxiliary' ? new DiagnosticProbe(`${output}.observations`, bench) : null;
if (probe) {
  const originalMeasure = bench.measure.bind(bench);
  bench.measure = async (id, fixture, bytes, fn) => {
    probe.boundary('operation-before', id, fixture);
    try { return await originalMeasure(id, fixture, bytes, fn); }
    finally { probe.boundary('operation-after', id, fixture); }
  };
}

/* ORIGINAL_RULES_CYCLE */

try {
  bench.fixture('synthetic-circuit-rules', 'circuit', new Uint8Array());
  bench.report.gaps.push('Rules-only auxiliary isolation excludes WLD document, region, TCW and largeWorld prefixes; no browser frames, real WLD or whole-suite acceptance.',
    'Fixture hashes and original correctness assertions are retained; not every mutation/packet has a cross-version canonical output hash.');
  bench.memory('baseline');
  bench.write(output, 'running');
  for (bench.cycle = -1; bench.cycle < bench.warmup + bench.cycles; bench.cycle++) {
    probe?.startCycle(bench.cycle);
    await rulesCycle();
    await bench.afterClose();
    bench.write(output, 'running');
    if (probe) await probe.endCycle();
  }
  if (rules) rules.invoke('dispose', []);
  await probe?.close();
  bench.write(output);
  console.log(`PASS auxiliary rules-only: ${bench.report.operations.length} rows; no full-suite acceptance`);
} catch (error) {
  try { await probe?.close(); } catch (observationError) { console.error(observationError); }
  bench.write(output, 'failed');
  console.error(error);
  process.exitCode = 1;
}
